    js: "'use strict';\nconst $=(s)=>document.querySelector(s);const canvas=$('#view');const ctx=canvas.getContext('2d');const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let W=640,H=400;const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));function fit(){const r=canvas.parentElement.getBoundingClientRect();W=r.width;H=r.height;const d=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(W*d);canvas.height=Math.round(H*d);ctx.setTransform(d,0,0,d,0,0);paint();}new ResizeObserver(fit).observe(canvas.parentElement);function line(points,color,width=1){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.stroke();}function circle(x,y,r,fill){ctx.fillStyle=fill;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();}function grid(color='#ffffff0a'){for(let x=0;x<W;x+=32)line([[x,0],[x,H]],color);for(let y=0;y<H;y+=32)line([[0,y],[W,y]],color);}function on(s,event,fn){$(s).addEventListener(event,fn);}function status(s){$('#status').textContent=s;}let seed=18,px=.67,py=.58,transect=false;const mod289=x=>x-Math.floor(x/289)*289,permute=x=>mod289((x*34+10)*x),fract=x=>x-Math.floor(x);function noise(x,y){const F=.366025403784439,G=.211324865405187,i=Math.floor(x+(x+y)*F),j=Math.floor(y+(x+y)*F),x0=x-i+(i+j)*G,y0=y-j+(i+j)*G,ix=x0>y0?1:0,iy=1-ix;const corners=[[x0,y0,0,0],[x0-ix+G,y0-iy+G,ix,iy],[x0-1+2*G,y0-1+2*G,1,1]];let out=0;corners.forEach(([cx,cy,dx,dy])=>{const p=permute(permute(mod289(j)+dy)+mod289(i)+dx);const gx=2*fract(p/41)-1,h=Math.abs(gx)-.5,ox=Math.floor(gx+.5),a=gx-ox,m=Math.max(.5-cx*cx-cy*cy,0);out+=m**4*(1.79284291400159-.85373472095314*(a*a+h*h))*(a*cx+h*cy);});return out*130;}function height(x,y){const nx=x*3.8+seed*.71,ny=y*3.8-seed*.47;return clamp(.48+noise(nx,ny)*.24+noise(nx*2,ny*2)*.11+noise(nx*4,ny*4)*.045,0,1);}function paint(){const sea=Number($('#sea').value)/100,interval=Number($('#interval').value)/100,blue=$('#mapmode').value==='1';ctx.fillStyle=blue?'#112b42':'#142b2d';ctx.fillRect(0,0,W,H);const step=3;for(let y=0;y<H;y+=step)for(let x=0;x<W;x+=step){const h=height(x/W,y/H),contour=(h/interval)%1<.095;if(h<sea)ctx.fillStyle=blue?'#15334b':h<sea-.08?'#183a43':'#315a61';else{let level=(h-sea)/(1-sea);ctx.fillStyle=blue?'hsl(199,35%,'+(23+level*21)+'%)':'hsl('+(85-level*30)+',20%,'+(34+level*29)+'%)';}ctx.fillRect(x,y,step+.3,step+.3);}const size=7,cols=Math.ceil(W/size),rows=Math.ceil(H/size),field=Array.from({length:rows+1},(_,y)=>Array.from({length:cols+1},(_,x)=>height(x*size/W,y*size/H)));for(let lev=sea;lev<.93;lev+=interval){for(let y=0;y<rows;y++)for(let x=0;x<cols;x++){const vals=[field[y][x],field[y][x+1],field[y+1][x+1],field[y+1][x]],pts=[[x*size,y*size],[(x+1)*size,y*size],[(x+1)*size,(y+1)*size],[x*size,(y+1)*size]],hits=[];for(let e=0;e<4;e++){let f=(e+1)%4;if((vals[e]<lev)!==(vals[f]<lev)){const t=(lev-vals[e])/(vals[f]-vals[e]);hits.push([pts[e][0]+(pts[f][0]-pts[e][0])*t,pts[e][1]+(pts[f][1]-pts[e][1])*t]);}}for(let j=0;j+1<hits.length;j+=2)line([hits[j],hits[j+1]],blue?'#a6dceacc':'#dee3bba8',lev===sea?1.5:.8);}}grid(blue?'#c5e9ef14':'#eef0c914');const x=px*W,y=py*H;if(transect){line([[0,y],[W,y]],'#f5eac788',1);ctx.fillStyle='#071b26dc';ctx.fillRect(15,H-78,W-30,53);const points=[];for(let i=0;i<=90;i++)points.push([20+(W-40)*i/90,H-32-height(i/90,py)*40]);line(points,'#eed697',1.7);ctx.font='9px system-ui';ctx.fillStyle='#d8e7c4';ctx.fillText('A — A′ / ELEVATION PROFILE',25,H-61);}line([[x-13,y],[x+13,y]],'#fff3c8',1.5);line([[x,y-13],[x,y+13]],'#fff3c8',1.5);circle(x,y,3,'#f1d27b');$('#sheet').textContent='SHEET '+String(seed).padStart(3,'0')+' / SYNTHETIC ISLAND';const elevation=Math.round(height(px,py)*2300);$('#probe').textContent='E '+(px*100).toFixed(2)+' / N '+(py*100).toFixed(2)+' / '+elevation+' M';status('档案种子 '+seed+' · 海平面 '+$('#sea').value+'% · 等高线 '+$('#interval').value+'% · 探针高程 '+elevation+' m（虚构） · '+(blue?'测绘蓝图':'矿物色谱')+' · '+(transect?'剖面线开启':'平面测绘'));}['#sea','#interval','#mapmode'].forEach(s=>on(s,s==='#mapmode'?'change':'input',paint));on('#seed','click',()=>{seed+=7;paint();});on('#transect','click',()=>{transect=!transect;$('#transect').setAttribute('aria-pressed',String(transect));paint();});on('#center','click',()=>{px=.5;py=.5;paint();});canvas.addEventListener('pointerdown',e=>{const r=canvas.getBoundingClientRect();px=clamp((e.clientX-r.left)/r.width,0,1);py=clamp((e.clientY-r.top)/r.height,0,1);paint();});fit();",
