    js: "'use strict';\nconst $=(s)=>document.querySelector(s);const canvas=$('#view');const ctx=canvas.getContext('2d');const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let W=640,H=400;const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));function fit(){const r=canvas.parentElement.getBoundingClientRect();W=r.width;H=r.height;const d=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(W*d);canvas.height=Math.round(H*d);ctx.setTransform(d,0,0,d,0,0);paint();}new ResizeObserver(fit).observe(canvas.parentElement);function line(points,color,width=1){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.stroke();}function circle(x,y,r,fill){ctx.fillStyle=fill;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();}function grid(color='#ffffff0a'){for(let x=0;x<W;x+=32)line([[x,0],[x,H]],color);for(let y=0;y<H;y+=32)line([[0,y],[W,y]],color);}function on(s,event,fn){$(s).addEventListener(event,fn);}function status(s){$('#status').textContent=s;}let progress=2.7,playing=false,yaw=0,pitch=0,checkpoints=0;function route(z){const kind=Number($('#route').value);if(kind===1)return [Math.sin(z*.4)*.7,Math.sin(z*.21)*.24];if(kind===2)return [Math.cos(z*.45)*.6,Math.sin(z*.45)*.46];return [Math.sin(z*.24)*.54,Math.cos(z*.38)*.28];}function paint(){ctx.fillStyle='#080d1b';ctx.fillRect(0,0,W,H);const central=route(progress);const rings=[],sides=Number($('#segments').value);for(let i=37;i>=0;i--){const z=(i+1)/4,near=route(progress+z),scale=Math.min(W,H)*.47/(z*.23+.16);const cx=W*.5+(near[0]-central[0])*W*.18+yaw*W*.12/(z*.1+1),cy=H*.58+(near[1]-central[1])*H*.2+pitch*H*.12/(z*.1+1);const points=[];for(let j=0;j<=sides;j++){let a=j/sides*Math.PI*2+.4;points.push([cx+Math.cos(a)*scale,cy+Math.sin(a)*scale]);}rings.push(points);const hue=Number($('#route').value)===1?31+i*.8:178+i*2;line(points,'hsla('+hue+',80%,68%,'+(1-i/42)*.65+')',i<4?1.8:1);if(i%4===0){ctx.shadowBlur=12;ctx.shadowColor='hsl('+hue+',80%,55%)';line(points,'hsla('+hue+',80%,68%,.24)',4);ctx.shadowBlur=0;}}for(let j=0;j<sides;j++){const points=rings.map(p=>p[j]);line(points,'#90aaf52b',1);}ctx.fillStyle='#a9bbed';ctx.font='9px monospace';for(let i=0;i<7;i++){const x=W*.1+i*W*.12;ctx.fillRect(x,H-28,1,8);ctx.fillText(String(i*30),x-6,H-10);}$('#distance').textContent='DISTANCE / '+(progress*.9).toFixed(1).padStart(5,'0')+' KM · LOG '+checkpoints;$('#routeName').textContent='ROUTE 0'+(Number($('#route').value)+1)+' / '+$('#route').selectedOptions[0].textContent;$('#steering').textContent='YAW '+Math.round(yaw*30)+'° / PITCH '+Math.round(pitch*30)+'°';status('航路 '+$('#route').selectedOptions[0].textContent+' · 速度 '+$('#speed').value+'% · '+sides+' 边截面 · '+(playing?'正在航行':'检查点冻结')+' · 记录 '+checkpoints);}function tick(){if(!playing)return;progress+=Number($('#speed').value)*.0008;paint();requestAnimationFrame(tick);}function stop(){playing=false;$('#launch').textContent='启航';$('#launch').setAttribute('aria-pressed','false');paint();}on('#launch','click',()=>{playing=!playing;$('#launch').textContent=playing?'暂停航行':'启航';$('#launch').setAttribute('aria-pressed',String(playing));if(playing)tick();else paint();});on('#checkpoint','click',()=>{checkpoints++;stop();});on('#align','click',()=>{yaw=0;pitch=0;paint();});['#route','#speed','#segments'].forEach(s=>on(s,s==='#speed'?'input':'change',paint));canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();yaw=clamp((e.clientX-r.left)/r.width*2-1,-1,1);pitch=clamp((e.clientY-r.top)/r.height*2-1,-1,1);paint();});fit();",
