    js: "'use strict';\nconst $=(s)=>document.querySelector(s);const canvas=$('#view');const ctx=canvas.getContext('2d');const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let W=640,H=400;const clamp=(v,a,b)=>Math.max(a,Math.min(b,v));function fit(){const r=canvas.parentElement.getBoundingClientRect();W=r.width;H=r.height;const d=Math.min(devicePixelRatio||1,2);canvas.width=Math.round(W*d);canvas.height=Math.round(H*d);ctx.setTransform(d,0,0,d,0,0);paint();}new ResizeObserver(fit).observe(canvas.parentElement);function line(points,color,width=1){ctx.strokeStyle=color;ctx.lineWidth=width;ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p[0],p[1]):ctx.moveTo(p[0],p[1]));ctx.stroke();}function circle(x,y,r,fill){ctx.fillStyle=fill;ctx.beginPath();ctx.arc(x,y,r,0,Math.PI*2);ctx.fill();}function grid(color='#ffffff0a'){for(let x=0;x<W;x+=32)line([[x,0],[x,H]],color);for(let y=0;y<H;y+=32)line([[0,y],[W,y]],color);}function on(s,event,fn){$(s).addEventListener(event,fn);}function status(s){$('#status').textContent=s;}const works=[['Ocean frequency.','海洋频率',190,182],['Folded sunset.','日落折叠',22,321],['Night polyphony.','夜色复调',250,290],['Tundra breath.','苔原呼吸',103,51],['Mineral echo.','矿物回声',31,181],['Pages of space.','深空书页',222,318]];let pointer=[0,0],explain=false;function poster(index,x,y,w,h,alpha){const a=works[index%6];ctx.save();ctx.globalAlpha=alpha;ctx.translate(x,y);ctx.fillStyle='hsl('+a[2]+',43%,24%)';ctx.fillRect(-w/2,-h/2,w,h);ctx.beginPath();ctx.rect(-w/2,-h/2,w,h);ctx.clip();for(let i=0;i<26;i++){const k=i/26;ctx.strokeStyle='hsla('+(a[2]+(a[3]-a[2])*k)+',70%,'+(48+k*18)+'%,.95)';ctx.lineWidth=w*.023;ctx.beginPath();ctx.ellipse(Math.sin(index)*w*.1,h*.07,w*(.14+k*.46),h*(.1+k*.34),index*.27,0,Math.PI*2);ctx.stroke();}ctx.fillStyle='hsla('+a[3]+',90%,76%,.48)';ctx.fillRect(-w*.25,-h*.45,w*.15,h*.9);ctx.fillStyle='#eff5e0';ctx.font='bold '+Math.max(8,w*.06)+'px system-ui';ctx.fillText('CHROMA / 0'+(index%6+1),-w*.4,h*.36);ctx.font=Math.max(7,w*.033)+'px system-ui';ctx.fillText(a[1],-w*.4,h*.43);ctx.restore();}function paint(){const index=Number($('#artwork').value),a=works[index],depth=Number($('#depth').value)/100;const grad=ctx.createRadialGradient(W*.63,H*.53,0,W*.6,H*.5,W*.72);grad.addColorStop(0,'hsl('+a[2]+',37%,'+(Number($('#mood').value)*.3)+'%)');grad.addColorStop(1,'#090f19');ctx.fillStyle=grad;ctx.fillRect(0,0,W,H);grid('#ffffff06');line([[W*.13,H*.79],[W*.91,H*.79]],'#c8ddd41f');const center=W<450?W*.53:W*.62;poster(index+2,center+W*.24+pointer[0]*4,H*.46+pointer[1]*3,W*(.19-depth*.06),H*.42,.25);poster(index+1,center-W*.16+pointer[0]*8,H*.5+pointer[1]*5,W*(.24-depth*.05),H*.55,.6);poster(index,center+pointer[0]*15,H*.56+pointer[1]*10,Math.min(W*.35+depth*W*.08,250),H*.71,1);$('#workTitle').textContent=a[0].replace(' ','\\n');$('#workMeta').textContent=String(index+1).padStart(2,'0')+' / 06 · '+a[1];$('#depthLabel').textContent='DEPTH / '+depth.toFixed(2)+' · '+$('#mood').value+'% AMBIENCE';status('档案 '+(index+1)+' / 6 · '+a[1]+' · 景深 '+$('#depth').value+'% · 环境亮度 '+$('#mood').value+'% · '+(explain?'解读已展开':'展览模式'));}function select(delta){$('#artwork').value=String((Number($('#artwork').value)+delta+6)%6);paint();}on('#previous','click',()=>select(-1));on('#next','click',()=>select(1));on('#explain','click',()=>{explain=!explain;$('#note').hidden=!explain;$('#explain').setAttribute('aria-pressed',String(explain));paint();});['#artwork','#depth','#mood'].forEach(s=>on(s,s==='#artwork'?'change':'input',paint));canvas.addEventListener('pointermove',e=>{const r=canvas.getBoundingClientRect();pointer=[(e.clientX-r.left)/r.width*2-1,(e.clientY-r.top)/r.height*2-1];paint();});canvas.addEventListener('pointerleave',()=>{pointer=[0,0];paint();});fit();",
